export const getAdminStatsTableUrl = (group: string,
    params: AdminStatsTableParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/admin/stats/tables/${group}?${stringifiedParams}` : `/admin/stats/tables/${group}`
}

